package com.astrocare.service;
import com.astrocare.dto.*; import com.astrocare.entity.*; import com.astrocare.exception.*; import com.astrocare.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class MarkerService {private final AnatomicalMarkerRepository markers;private final AstronautRepository astronauts;private final UserRepository users; public List<MarkerResponse> list(Long id){return markers.findByAstronautIdOrderByCreatedAtDesc(id).stream().map(MarkerResponse::from).toList();} public MarkerResponse create(MarkerRequest r,String username){Astronaut a=astronauts.findById(r.astronautId()).orElseThrow(()->new ResourceNotFoundException("Astronaut not found"));AnatomicalMarker m=new AnatomicalMarker();m.setAstronaut(a);m.setBodyZone(r.bodyZone());m.setCoordX(r.coordX());m.setCoordY(r.coordY());m.setSeverity(r.severity());m.setClinicalNote(r.clinicalNote());m.setCreatedBy(users.findByUsername(username).orElse(null));return MarkerResponse.from(markers.save(m));}}
